{
  "root_causes": [
    {
      "service": "ts-payment-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, min(time)::VARCHAR t0, max(time)::VARCHAR t1, min(value) mn, max(value) mx, count(*) n FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-payment%' GROUP BY ALL",
          "claim": "ts-payment-service pod restart counter rose from 0 to 1 during the incident; normal period shows 0 restarts."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'norm' p, count(*) n, min(time)::VARCHAR t0, max(time)::VARCHAR t1 FROM normal_traces WHERE service_name='ts-payment-service' AND attr_span_kind='Server' UNION ALL SELECT 'abn', count(*), min(time)::VARCHAR, max(time)::VARCHAR FROM abnormal_traces WHERE service_name='ts-payment-service' AND attr_span_kind='Server'",
          "claim": "Payment server spans fall from 33 in the normal period to 19 in a short gap during the incident."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, substr(message,1,220) msg, count(*) n FROM abnormal_logs WHERE service_name='ts-inside-payment-service' AND level='SEVERE' GROUP BY ALL",
          "claim": "Inside-payment logs 19 SEVERE 503 errors: upstream connect error, 'Connection refused' from the payment service."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-payment-service",
      "to": "ts-inside-payment-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name callee, c.span_name, count(*) n, round(avg(p.duration)/1e6,1) client_ms, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-inside-payment-service' AND p.span_name LIKE 'POST%' AND p.attr_span_kind='Client' GROUP BY ALL",
          "claim": "Inside-payment's POST calls to payment average about 1.8 s with 19 of 39 failing; only 19 reached payment."
        }
      ]
    },
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, count(*) n, round(avg(c.duration)/1e6,1) avg_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE s.service_name='ts-inside-payment-service' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "ts-ui-dashboard calls inside-payment's pay endpoint; those 40 calls average about 9.3 s in the incident."
        }
      ]
    }
  ]
}
